            elif node['text']:
                label = f"{node['text']}"
            f.write(f'  "{node["id"]}" [label="{label}"];\n')

        for edge in graph["edges"]:
            f.write(f'  "{edge["from"]}" -> "{edge["to"]}" [label="{edge["text"]}"];\n')
        f.write("}\n")

