import re

def parse_script(text: str):
    nodes = []
    edges = []

    # Split text into blocks by [NodeName]
    # We use a non-capturing group for the split but keep the node names
    blocks = re.split(r'\[(.*?)\]', text)

    for i in range(1, len(blocks), 2):
        node_id = blocks[i].strip()
        content = blocks[i+1].strip()

        lines = [line.strip() for line in content.split('\n') if line.strip()]

        if not lines:
            continue

        # Check if it's a choice node or a line node
        is_choice = any(re.match(r'^\d+\.', line) for line in lines)

        if is_choice:
            node = {
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "choice"
            }
            nodes.append(node)

            for line in lines:
                match = re.match(r'^(\d+)\.\s*(.*?)\s*->\s*(.*)$', line)
                if match:
                    edge_text = match.group(2).strip()
                    target = match.group(3).strip()
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": edge_text
                    })
        else:
            # Assume it's a line node
            # Example: Speaker: Text -> Target
            found_line = False
            for line in lines:
                match = re.match(r'^(.*?):\s*(.*?)\s*->\s*(.*)$', line)
                if match:
                    speaker = match.group(1).strip()
                    text_content = match.group(2).strip()
                    target = match.group(3).strip()

                    node = {
                        "id": node_id,
                        "text": text_content,
                        "speaker": speaker,
                        "type": "line"
                    }
                    nodes.append(node)

                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": ""
                    })
                    found_line = True
                    break

            if not found_line:
                # Fallback if no speaker found but there's a transition
                for line in lines:
                    match = re.match(r'^(.*?)\s*->\s*(.*)$', line)
                    if match:
                        text_content = match.group(1).strip()
                        target = match.group(2).strip()
                        node = {
                            "id": node_id,
                            "text": text_content,
                            "speaker": "",
                            "type": "line"
                        }
                        nodes.append(node)
                        edges.append({
                            "from": node_id,
                            "to": target,
                            "text": ""
                        })
                        found_line = True
                        break

    # Add targets that are not defined as nodes
    node_ids = {n["id"] for n in nodes}
    referenced_targets = {e["to"] for e in edges}
    for target in referenced_targets:
        if target not in node_ids:
            nodes.append({
                "id": target,
                "text": "",
                "speaker": "",
                "type": "line"
            })
            node_ids.add(target)

    return {"nodes": nodes, "edges": edges}

if __name__ == "__main__":
    with open("/app/script.txt", "r") as f:
        script_text = f.read()

    graph = parse_script(script_text)

    with open("/app/dialogue.json", "w") as f:
        json.dump(graph, f, indent=2)

    with open("/app/dialogue.dot", "w") as f:
        f.write("digraph G {\n")
        f.write("  node [shape=box];\n")
        for node in graph["nodes"]:
            label = node['id']
            if node['speaker']:
                label = f"{node['speaker']}\\n{node['text']}"
            elif node['text']:
                label = node['text']

            # Escape quotes for DOT
            label = label.replace('"', '\\"')
            f.write(f'  "{node["id"]}" [label="{label}"];\n')

        for edge in graph["edges"]:
            edge_text = edge["text"].replace('"', '\\"')
            f.write(f'  "{edge["from"]}" -> "{edge["to"]}" [label="{edge_text}"];\n')
        f.write("}\n")

