    blocks = re.split(r'\[(.*?)\]', text)

    node_id_to_data = {}

    first_node_id = None

    for i in range(1, len(blocks), 2):
        node_id = blocks[i].strip()
        if first_node_id is None:
            first_node_id = node_id

        content = blocks[i+1].strip()
        lines = [line.strip() for line in content.split('\n') if line.strip()]

        if not lines:
            continue

        is_choice = any(re.match(r'^\d+\.', line) for line in lines)

        if is_choice:
            node_id_to_data[node_id] = {
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "choice"
            }

            for line in lines:
                match = re.match(r'^(\d+)\.\s*(.*?)\s*->\s*(.*)$', line)
                if match:
                    edge_text = match.group(2).strip()
                    target = match.group(3).strip()
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": edge_text
                    })
        else:
            found_line = False
            for line in lines:
                match = re.match(r'^(.*?):\s*(.*?)\s*->\s*(.*)$', line)
                if match:
                    speaker = match.group(1).strip()
                    text_content = match.group(2).strip()
                    target = match.group(3).strip()

                    node_id_to_data[node_id] = {
                        "id": node_id,
                        "text": text_content,
                        "speaker": speaker,
                        "type": "line"
                    }
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": ""
                    })
                    found_line = True
                    break

            if not found_line:
                for line in lines:
                    match = re.match(r'^(.*?)\s*->\s*(.*)$', line)
                    if match:
                        text_content = match.group(1).strip()
                        target = match.group(2).strip()
                        node_id_to_data[node_id] = {
                            "id": node_id,
                            "text": text_content,
                            "speaker": "",
                            "type": "line"
                        }
                        edges.append({
                            "from": node_id,
                            "to": target,
                            "text": ""
                        })
                        found_line = True
                        break

    # Add missing nodes that are targets
    referenced_targets = {e["to"] for e in edges}
    for target in referenced_targets:
        if target not in node_id_to_data:
            node_id_to_data[target] = {
                "id": target,
                "text": "",
                "speaker": "",
                "type": "line"
            }

    # Reachability check from first_node_id
    if not first_node_id:
        return {"nodes": [], "edges": []}

    reachable_nodes = set()
    queue = deque([first_node_id])
    reachable_nodes.add(first_node_id)

    adj = {}
    for edge in edges:
        f = edge["from"]
        t = edge["to"]
        if f not in adj: adj[f] = []
        adj[f].append(t)

    while queue:
        curr = queue.popleft()
        for neighbor in adj.get(curr, []):
            if neighbor not in reachable_nodes:
                reachable_nodes.add(neighbor)
                queue.append(neighbor)

    # Filter nodes and edges
    final_nodes = [node_id_to_data[nid] for nid in sorted(reachable_nodes) if nid in node_id_to_data]
    final_edges = [e for e in edges if e["from"] in reachable_nodes and e["to"] in reachable_nodes]

    return {"nodes": final_nodes, "edges": final_edges}

